export interface ContentBlock {
  id: string;
  type:
    | "clinical_overview"
    | "symptoms_checklist"
    | "causes_risk_factors"
    | "diagnostic_criteria"
    | "treatment_medications"
    | "self_care_lifestyle"
    | "when_to_see_doctor"
    | "comparison_table"
    | "alert_callout"
    | "standard_rich_text";
  heading?: string;
  content?: string;
  items?: string[];
  columns?: string[];
  rows?: (string[] | { cells: string[] } | any)[];
  alertType?: "info" | "important" | "warning" | "emergency";
  multiColumn?: boolean;
}

export interface ReferenceItem {
  id: string;
  title: string;
  author?: string;
  url: string;
  publishDate?: string;
  citation?: string;
}

export interface BlogPost {
  id: string;
  slug: string;
  title: string;
  category: string;
  summary: string;
  content?: string;
  publishedAt: string;
  featuredImage: string;
  author: string;
  readTime: string;
  
  // Advanced CMS fields
  status?: "Published" | "Draft" | "Scheduled";
  seoScore?: number;
  views?: number;
  updatedAt?: string;
  imageAlt?: string;
  imageCaption?: string;
  imageCredit?: string;
  videoUrl?: string;
  relatedArticles?: string[];
  featured?: boolean;
  trending?: boolean;
  tags?: string[];
  metaTitle?: string;
  metaDescription?: string;
  focusKeyphrase?: string;
  schemaType?: string;
  robotsMeta?: string;
  canonicalUrl?: string;
  visibility?: string;
  allowComments?: boolean;
  lastReviewedDate?: string;
  reviewFrequency?: string;
  language?: string;
  versionNumber?: string;

  // Structured Medical Fields
  medicalReviewer?: string;
  medicalReviewedAt?: string;
  reviewCycle?: "6 months" | "12 months" | "24 months";
  subcategory?: string;
  quickAnswer?: string;
  introduction?: string;
  contentBlocks?: ContentBlock[];
  faqs?: FAQItem[];
  references?: ReferenceItem[];
  disclaimerType?: "clinical" | "insurance" | "wellness" | "full_medical";
}

export interface FAQItem {
  id: string;
  question: string;
  answer: string;
  category?: string;
  status?: string;
}

export interface ProfessionalProfileLink {
  platform: string;
  url: string;
  label: string;
}

export interface ProfessionalProfile {
  id: string;
  name: string;
  credentials: string;
  degree?: string;
  title: string;
  bio?: string;
  avatarUrl?: string;
  specialty?: string;
  experience?: string;
  licenseNumber?: string;
  licensingBody?: string;
  licenseStatus?: string;
  education?: string[];
  thesisTitle?: string;
  thesisInstitution?: string;
  thesisSummary?: string;
  publicationsCount?: string;
  keyResearchAreas?: string[];
  hospitalAffiliations?: string;
  areasReviewed?: string[];
  conflictOfInterest?: string;
  externalProfiles?: ProfessionalProfileLink[];
  roleType?: "Physician Reviewer" | "Senior Medical Editor" | "Clinical Specialist" | "Editorial Team";
}

